-- Authenticated internal intake. A form never grants record or field access.
-- No existing grant is expanded and no public/anonymous channel is added.
ALTER TABLE hs_data_collection_grants DROP CONSTRAINT IF EXISTS hs_data_collection_grants_capabilities_check;
ALTER TABLE hs_data_collection_grants ADD CONSTRAINT hs_data_collection_grants_capabilities_check CHECK(capabilities <@ ARRAY['view','create','edit','link','import','export','bulk','archive','delete','restore','merge','schema','manage-views','history','restore-values','manage-templates','manage-permissions','manage-forms']::text[]);
ALTER TABLE hs_data_schema_dependencies DROP CONSTRAINT IF EXISTS hs_data_schema_dependencies_kind_check;
ALTER TABLE hs_data_schema_dependencies ADD CONSTRAINT hs_data_schema_dependencies_kind_check CHECK(kind IN ('view','import-mapping','integration','reference-policy','template','intake'));
ALTER TABLE hs_data_schema_dependencies ADD COLUMN IF NOT EXISTS intake_form_id uuid;
CREATE TABLE IF NOT EXISTS hs_data_intake_catalogues(tenant_id uuid NOT NULL,collection text NOT NULL,revision integer NOT NULL DEFAULT 1,PRIMARY KEY(tenant_id,collection),FOREIGN KEY(tenant_id,collection) REFERENCES hs_data_collections(tenant_id,id));
CREATE TABLE IF NOT EXISTS hs_data_intake_forms(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,collection text NOT NULL,name text NOT NULL CHECK(char_length(btrim(name)) BETWEEN 1 AND 100),name_search text GENERATED ALWAYS AS(lower(name)) STORED,version integer NOT NULL DEFAULT 1 CHECK(version>0),deprecated boolean NOT NULL DEFAULT false,definition jsonb NOT NULL,created_by text NOT NULL REFERENCES hs_users(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,collection,name_search),FOREIGN KEY(tenant_id,collection) REFERENCES hs_data_collections(tenant_id,id));
ALTER TABLE hs_data_schema_dependencies DROP CONSTRAINT IF EXISTS hs_data_schema_dependencies_intake_form_id_fkey;
ALTER TABLE hs_data_schema_dependencies ADD CONSTRAINT hs_data_schema_dependencies_intake_form_id_fkey FOREIGN KEY(intake_form_id) REFERENCES hs_data_intake_forms(id);
CREATE INDEX IF NOT EXISTS hs_data_intake_form_catalogue ON hs_data_intake_forms(tenant_id,collection,name_search,id) WHERE deprecated=false;
CREATE TABLE IF NOT EXISTS hs_data_intake_form_versions(tenant_id uuid NOT NULL,form_id uuid NOT NULL,version integer NOT NULL,name text NOT NULL,deprecated boolean NOT NULL,definition jsonb NOT NULL,schema_version integer NOT NULL,actor_id text NOT NULL REFERENCES hs_users(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,form_id,version),FOREIGN KEY(tenant_id,form_id) REFERENCES hs_data_intake_forms(tenant_id,id));
CREATE TABLE IF NOT EXISTS hs_data_intake_form_operations(tenant_id uuid NOT NULL REFERENCES hs_data_tenants(id),actor_id text NOT NULL REFERENCES hs_users(id),operation_id uuid NOT NULL,request_hash text NOT NULL,form_id uuid NOT NULL,applied_version integer NOT NULL,PRIMARY KEY(tenant_id,actor_id,operation_id),FOREIGN KEY(tenant_id,form_id) REFERENCES hs_data_intake_forms(tenant_id,id));
CREATE TABLE IF NOT EXISTS hs_data_intake_submissions(tenant_id uuid NOT NULL,actor_id text NOT NULL REFERENCES hs_users(id),operation_id uuid NOT NULL,request_hash text NOT NULL,form_id uuid NOT NULL,form_version integer NOT NULL,record_id uuid NOT NULL,applied_version integer NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,actor_id,operation_id),FOREIGN KEY(tenant_id,record_id) REFERENCES hs_data_records(tenant_id,id),FOREIGN KEY(tenant_id,form_id,form_version) REFERENCES hs_data_intake_form_versions(tenant_id,form_id,version));
DROP TRIGGER IF EXISTS hs_data_intake_form_versions_immutable ON hs_data_intake_form_versions;
CREATE TRIGGER hs_data_intake_form_versions_immutable BEFORE UPDATE OR DELETE ON hs_data_intake_form_versions FOR EACH ROW EXECUTE FUNCTION hs_data_history_immutable();
DROP TRIGGER IF EXISTS hs_data_intake_submissions_immutable ON hs_data_intake_submissions;
CREATE TRIGGER hs_data_intake_submissions_immutable BEFORE UPDATE OR DELETE ON hs_data_intake_submissions FOR EACH ROW EXECUTE FUNCTION hs_data_history_immutable();
CREATE OR REPLACE FUNCTION hs_data_intake_form_identity_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.id<>OLD.id OR NEW.tenant_id<>OLD.tenant_id OR NEW.collection<>OLD.collection OR NEW.created_by<>OLD.created_by OR NEW.created_at<>OLD.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Intake form identity and collection are immutable'; END IF;RETURN NEW;END $$;
DROP TRIGGER IF EXISTS hs_data_intake_form_identity_guard ON hs_data_intake_forms;
CREATE TRIGGER hs_data_intake_form_identity_guard BEFORE UPDATE ON hs_data_intake_forms FOR EACH ROW EXECUTE FUNCTION hs_data_intake_form_identity_guard();
